53	const PROCESSING_FEE = 5;
54	const FIRST_INSURANCE_RATE = 0.1;
55	const CURSE_SURCHARGE_RATE = 0.5;
56	
57	const BASE_PREMIUMS: Record<string, number> = {
58	  sword: 100,
59	  amulet: 60,
60	  staff: 80,
61	  potion: 40,
62	  rune: 25,
63	  moonstone: 25,
64	};
65	
66	// "A building block of 3 alike components is offered at a special base premium of 60 G."
67	const COMPONENT_TYPES = ["rune", "moonstone"];
68	const BLOCK_SIZE = 3;
69	const COMPONENT_BLOCK_PREMIUM = 60;
70	
71	const quotePremium = (items: QuoteItem[]): number => {
72	  const itemBase = items.reduce(
73	    (sum, item) => sum + BASE_PREMIUMS[item.type],
74	    0,
75	  );
76	  const blockDiscount = COMPONENT_TYPES.reduce((discount, type) => {
77	    const count = items.filter((item) => item.type === type).length;
78	    return count === BLOCK_SIZE
79	      ? discount + BLOCK_SIZE * BASE_PREMIUMS[type] - COMPONENT_BLOCK_PREMIUM
80	      : discount;
81	  }, 0);
82	  const policyBase = itemBase - blockDiscount;
83	  const curseSurcharge = items.reduce(
84	    (sum, item) =>
85	      sum + (item.cursed ? BASE_PREMIUMS[item.type] * CURSE_SURCHARGE_RATE : 0),
86	    0,
87	  );
88	  const enchantmentSurcharge = items.reduce(
89	    (sum, item) =>
90	      sum +
91	      ((item.enchantment ?? 0) >= 5 ? BASE_PREMIUMS[item.type] * 0.3 : 0),
92	    0,
93	  );
94	  const firstInsurance = policyBase * FIRST_INSURANCE_RATE;
95	  return Math.ceil(
96	    policyBase +
97	      curseSurcharge +
98	      enchantmentSurcharge +
99	      firstInsurance +
100	      PROCESSING_FEE,
101	  );
102	};
103	
104	export const runScenario = (scenario: Scenario): ScenarioOutput => {
105	  const quote = scenario.steps[0] as QuoteStep;
106	  return { results: [{ premium: quotePremium(quote.items) }] };
107	};
